public final class CircuitBreakerTest {
    static RuntimeException boomErr = new RuntimeException("boom");

    public static void main(String[] args) {
        checkTripsOpenAfterConsecutiveFailures();
        checkFailsFastWithoutCallingFnWhileOpen();
        checkHalfOpenTrialAfterTimeoutSuccessCloses();
        checkHalfOpenFailureReopensAndResetsClock();
        System.out.println("all tests passed");
    }

    static Object boom() {
        throw boomErr;
    }

    static void checkTripsOpenAfterConsecutiveFailures() {
        CircuitBreaker b = new CircuitBreaker(3, 10);
        for (int i = 0; i < 3; i++) {
            try {
                b.call(CircuitBreakerTest::boom, 0);
                throw new AssertionError("expected exception");
            } catch (RuntimeException e) {
                if (e != boomErr) throw new AssertionError("unexpected exception: " + e);
            }
        }
        try {
            b.call(() -> "should not run", 0);
            throw new AssertionError("expected CircuitOpenException");
        } catch (CircuitBreaker.CircuitOpenException e) {
            // expected
        }
    }

    static void checkFailsFastWithoutCallingFnWhileOpen() {
        CircuitBreaker b = new CircuitBreaker(1, 100);
        try {
            b.call(CircuitBreakerTest::boom, 0);
        } catch (RuntimeException e) {
            // expected
        }
        int[] calls = {0};
        try {
            b.call(() -> { calls[0]++; return 1; }, 1);
            throw new AssertionError("expected CircuitOpenException");
        } catch (CircuitBreaker.CircuitOpenException e) {
            // expected
        }
        if (calls[0] != 0) throw new AssertionError("fn must not be called while open");
    }

    static void checkHalfOpenTrialAfterTimeoutSuccessCloses() {
        CircuitBreaker b = new CircuitBreaker(1, 10);
        try {
            b.call(CircuitBreakerTest::boom, 0);
        } catch (RuntimeException e) {
            // expected
        }
        if (!"ok".equals(b.call(() -> "ok", 10))) throw new AssertionError("expected ok");
        if (!"still-fine".equals(b.call(() -> "still-fine", 11))) throw new AssertionError("expected still-fine");
    }

    static void checkHalfOpenFailureReopensAndResetsClock() {
        CircuitBreaker b = new CircuitBreaker(1, 10);
        try {
            b.call(CircuitBreakerTest::boom, 0);
        } catch (RuntimeException e) {
            // expected
        }
        try {
            b.call(CircuitBreakerTest::boom, 10);
            throw new AssertionError("expected boom at half-open trial");
        } catch (RuntimeException e) {
            if (e != boomErr) throw new AssertionError("unexpected exception: " + e);
        }
        try {
            b.call(() -> "too soon", 15);
            throw new AssertionError("expected CircuitOpenException at t=15");
        } catch (CircuitBreaker.CircuitOpenException e) {
            // expected
        }
        if (!"ok now".equals(b.call(() -> "ok now", 20))) throw new AssertionError("expected ok now at t=20");
    }
}

